        color = grid[r][0]
        if color != 0 and all(v == color for v in grid[r]):
            dividers.append((min(r, h - r - 1), "row", r))

    for c in range(w):
        color = grid[0][c]
        if color != 0 and all(grid[r][c] == color for r in range(h)):
            dividers.append((min(c, w - c - 1), "col", c))

    if not dividers:
        return []

    _, direction, pos = max(dividers)

    if direction == "row":
        n = min(pos, h - pos - 1)
        return [
            [
                2 if grid[pos - n + i][c] != 0 and grid[pos + 1 + i][c] != 0 else 0
                for c in range(w)
            ]
            for i in range(n)
        ]

    n = min(pos, w - pos - 1)
    return [
        [
            2 if grid[r][pos - n + j] != 0 and grid[r][pos + 1 + j] != 0 else 0
            for j in range(n)
        ]
        for r in range(h)
    ]
